const patients = $input.all();
if (patients.length > 0 && patients[0].json && patients[0].json.id) {
  return [{
    json: {
      registrado: true,
      patient_id: patients[0].json.id,
      nombre_niño: patients[0].json.first_name,
      apellidos: patients[0].json.last_name || ''
    }
  }];
} else {
  return [{
    json: {
      registrado: false
    }
  }];
}

let lead = {};
try {
  const inputData = $input.first().json.body.message?.toolCalls?.[0]?.function?.args?.datos_lead || $input.first().json.body.datos_lead;
  lead = typeof inputData === 'string' ? JSON.parse(inputData) : inputData;
} catch (e) {
  console.error("Error parsing datos_lead:", e);
}

return [{
  json: {
    nombre_padre: lead?.nombre_padre || 'Interesado',
    nombre_niño: lead?.nombre_niño || lead?.nombre_nino || 'Paciente Nuevo',
    telefono: lead?.telefono || ($input.first().json.body.message?.toolCalls?.[0]?.function?.args?.telefono_origen || $input.first().json.body.message?.customer?.number || $input.first().json.body.telefono_origen || '').toString().slice(-9),
    motivo: lead?.motivo || lead?.notas || lead?.observaciones || 'No especificado'
  }
}];

